1	package extproc
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7	
8		ext_proc "github.com/envoyproxy/go-control-plane/envoy/service/ext_proc/v3"
9		"github.com/openai/openai-go"
10		"google.golang.org/grpc/codes"
11		"google.golang.org/grpc/status"
12	
13		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/anthropic"
14		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
15		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/inflight"
16		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
17		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/metrics"
18	)
19	
20	func (r *OpenAIRouter) translateResponseAPIRequest(
21		requestBody []byte,
22		ctx *RequestContext,
23	) ([]byte, *ext_proc.ProcessingResponse) {
24		if ctx.ResponseAPICtx == nil || !ctx.ResponseAPICtx.IsResponseAPIRequest || r.ResponseAPIFilter == nil {
25			return requestBody, nil
26		}
27	
28		respCtx, translatedBody, err := r.ResponseAPIFilter.TranslateRequest(ctx.TraceContext, requestBody)
29		if err != nil {
30			logging.Errorf("Response API translation error: %v", err)
31			return nil, r.createErrorResponse(400, "Invalid Response API request: "+err.Error())
32		}
33		if respCtx == nil || translatedBody == nil {
34			logging.Errorf("Response API: Request to /v1/responses missing required 'input' field")
35			return nil, r.createErrorResponse(
36				400,
37				"Invalid Response API request: 'input' field is required. Use 'input' instead of 'messages' for Response API.",
38			)
39		}
40	
41		ctx.ResponseAPICtx = respCtx
42		populateSessionTransitionFields(ctx)
43		logging.ComponentDebugEvent("extproc", "response_api_request_translated", map[string]interface{}{
44			"request_id": ctx.RequestID,
45		})
46		return translatedBody, nil
47	}
48	
49	func (r *OpenAIRouter) extractFastRequestState(
50		requestBody []byte,
51		ctx *RequestContext,
52	) (*FastExtractResult, error) {
53		fast, err := extractRequestSignalsForProtocol(ctx.ClientProtocol, requestBody)
54		if err != nil {
55			logging.Errorf("Error extracting request fields: %v", err)
56			metrics.RecordRequestError(ctx.RequestModel, "parse_error")
57			metrics.RecordModelRequest(ctx.RequestModel)
58			return nil, status.Errorf(codes.InvalidArgument, "invalid request body: %v", err)
59		}
60		if fast.Stream {
61			logging.ComponentDebugEvent("extproc", "stream_parameter_detected", map[string]interface{}{
62				"request_id": ctx.RequestID,
63			})
64			ctx.ExpectStreamingResponse = true
65		}
66		return fast, nil
67	}
68	
69	// extractRequestSignalsForProtocol dispatches the gjson-based fast-extract
70	// walker by inbound wire format. OpenAI is the default (empty protocol);
71	// Anthropic /v1/messages uses the variant that understands the Anthropic
72	// content-block shape. Downstream signal consumers see the same
73	// FastExtractResult contract regardless of source protocol.
74	func extractRequestSignalsForProtocol(clientProtocol string, body []byte) (*FastExtractResult, error) {
75		switch clientProtocol {
76		case config.ClientProtocolAnthropic:
77			return extractContentFastAnthropic(body)
78		default:
79			return extractContentFast(body)
80		}
81	}
82	
83	// parseRequestForProtocol dispatches body parsing by inbound wire format.
84	// OpenAI is the default; Anthropic /v1/messages routes through the
85	// dedicated inbound parser, whose IRExtensions output is stashed on the
86	// request context for downstream emitters and plugins.
87	func parseRequestForProtocol(ctx *RequestContext, requestBody []byte) (*openai.ChatCompletionNewParams, error) {
88		if ctx.ClientProtocol != config.ClientProtocolAnthropic {
89			return parseOpenAIRequest(requestBody)
90		}
91		openAIRequest, ext, err := anthropic.ParseAnthropicRequest(requestBody)
92		if err != nil {
93			return nil, err
94		}
95		if ext != nil {
96			ctx.IRExtensions = ext
97		}
98		return openAIRequest, nil
99	}
100	
101	func (r *OpenAIRouter) runRequestPreRoutingStages(
102		originalModel string,
103		fast *FastExtractResult,
104		ctx *RequestContext,
105	) (requestDecisionState, *ext_proc.ProcessingResponse) {
106		r.resolveEntrypointForRequest(originalModel, ctx)
107		populatePinnedSessionFromHeaders(ctx)
108		history := signalConversationHistoryFromFastExtract(fast)
109		decisionName, _, reasoningDecision, selectedModel, decisionErr := r.performDecisionEvaluation(
110			originalModel,
111			history,
112			ctx,
113		)
114		if decisionErr != nil {
115			if errors.Is(decisionErr, context.Canceled) ||
116				errors.Is(decisionErr, context.DeadlineExceeded) {
117				return requestDecisionState{}, r.createErrorResponse(499, "request canceled")
118			}
119			logging.Errorf("[Request Body] Authz evaluation failed: %v", decisionErr)
120			return requestDecisionState{}, r.createErrorResponse(403, decisionErr.Error())
121		}
122	
123		metrics.RecordModelRequest(selectedModel)
124		ctx.InflightToken = inflight.Begin(selectedModel)
125		if resp := r.handleFastResponse(ctx, decisionName); resp != nil {
126			inflight.End(selectedModel, ctx.InflightToken)
127			ctx.InflightToken = 0
128			r.startRouterReplay(ctx, originalModel, selectedModel, decisionName)
129			r.updateRouterReplayStatus(ctx, 200, false)
130			r.attachRouterReplayResponse(
131				ctx,
132				resp.GetImmediateResponse().GetBody(),
133				true,
134			)
135			addRouterReplayHeaderToImmediateResponse(resp, ctx.RouterReplayID)
136			return requestDecisionState{}, resp
137		}
138		if resp := r.applyRateLimitAndCacheChecks(ctx, selectedModel, decisionName); resp != nil {
139			inflight.End(selectedModel, ctx.InflightToken)
140			ctx.InflightToken = 0
141			return requestDecisionState{}, resp
142		}
143		if ragErr := r.executeRAGPlugin(ctx, decisionName); ragErr != nil {
144			inflight.End(selectedModel, ctx.InflightToken)
145			ctx.InflightToken = 0
146			return requestDecisionState{}, r.createErrorResponse(503, fmt.Sprintf("RAG retrieval failed: %v", ragErr))
147		}
148	
149		return requestDecisionState{
150			decisionName:      decisionName,
151			reasoningDecision: reasoningDecision,
152			selectedModel:     selectedModel,
153		}, nil
154	}
155	
156	func (r *OpenAIRouter) applyRateLimitAndCacheChecks(
157		ctx *RequestContext,
158		selectedModel string,
159		decisionName string,
160	) *ext_proc.ProcessingResponse {
161		if r.RateLimiter != nil {
162			rlCtx := r.buildRateLimitContext(ctx, selectedModel)
163			decision, err := r.RateLimiter.Check(rlCtx)
164			if err != nil {
165				logging.ComponentErrorEvent("extproc", "rate_limit_check_failed", map[string]interface{}{
166					"request_id": ctx.RequestID,
167					"model":      selectedModel,
168					"error":      err.Error(),
169				})
170				return r.createRateLimitResponse(decision)
171			}
172			if decision != nil && !decision.Allowed {
173				logging.ComponentEvent("extproc", "rate_limit_rejected", map[string]interface{}{
174					"request_id":         ctx.RequestID,
175					"model":              rlCtx.Model,
176					"provider":           decision.Provider,
177					"remaining":          decision.Remaining,
178					"user_scope_present": rlCtx.UserID != "",
179				})
180				return r.createRateLimitResponse(decision)
181			}
182			ctx.RateLimitCtx = &rlCtx
183		}
184	
185		if response, shouldReturn := r.handleCaching(ctx, decisionName); shouldReturn {
186			logging.ComponentDebugEvent("extproc", "cache_short_circuit", map[string]interface{}{
187				"request_id": ctx.RequestID,
188				"decision":   decisionName,
189			})
190			return response
191		}
192		return nil
193	}
194	
195	func (r *OpenAIRouter) prepareRequestForModelRouting(
196		requestBody []byte,
197		userContent string,
198		ctx *RequestContext,
199	) (*openai.ChatCompletionNewParams, *ext_proc.ProcessingResponse, error) {
200		r.maybeForceImageGenerationModality(userContent, ctx)
201	
202		openAIRequest, err := parseRequestForProtocol(ctx, requestBody)
203		if err != nil {
204			logging.Errorf("Error parsing request for routing: %v", err)
205			metrics.RecordRequestError(ctx.RequestModel, "parse_error")
206			return nil, nil, status.Errorf(codes.InvalidArgument, "invalid request body: %v", err)
207		}
208	
209		// Store Chat Completion messages for memory extraction (if not Response API)
210		// Response API has its own conversation history via previous_response_id chain
211		if ctx.ResponseAPICtx == nil || !ctx.ResponseAPICtx.IsResponseAPIRequest {
212			ctx.ChatCompletionMessages = extractChatCompletionMessages(openAIRequest)
213			// Note: ChatCompletionUserID extraction is handled in user_id_dev.go for dev builds only.
214			// In production, user ID comes ONLY from the trusted auth header (x-authz-user-id).
215			// We store the raw request body to allow dev builds to extract it later.
216			ctx.ChatCompletionRequestBody = requestBody
217			populateSessionTransitionFields(ctx)
218		}
219	
220		if resp, err := r.handleModalityFromDecision(ctx, openAIRequest); err != nil {
221			logging.Errorf("[ModalityRouter] Error: %v", err)
222			return nil, r.createErrorResponse(503, fmt.Sprintf("Modality routing failed: %v", err)), nil
223		} else if resp != nil {
224			return nil, resp, nil
225		}
226	
227		requestBody, memErr := r.handleMemoryRetrieval(ctx, userContent, requestBody, openAIRequest)
228		if memErr != nil {
229			logging.ComponentWarnEvent("extproc", "memory_retrieval_failed", map[string]interface{}{
230				"request_id": ctx.RequestID,
231				"error":      memErr.Error(),
232				"fallback":   "continue_without_memory",
233			})
234		}
235		if ctx.MemoryContext != "" {
236			ctx.OriginalRequestBody = requestBody
237		}
238		r.refreshResponseAPITranslatedBody(ctx, requestBody)
239		openAIRequest = r.reparseRequestWithMemory(requestBody, openAIRequest, ctx)
240	
241		return openAIRequest, nil, nil
242	}
243	
244	func (r *OpenAIRouter) maybeForceImageGenerationModality(userContent string, ctx *RequestContext) {
245		if ctx.ResponseAPICtx == nil || !ctx.ResponseAPICtx.HasImageGenerationTool {
246			return
247		}
248		if ctx.ModalityClassification != nil && ctx.ModalityClassification.Modality != "" && ctx.ModalityClassification.Modality != ModalityAR {
249			return
250		}
251	
252		modality := ModalityDiffusion
253		if userContent != "" {
254			modality = ModalityBoth
255		}
256		ctx.ModalityClassification = &ModalityClassificationResult{
257			Modality:   modality,
258			Confidence: 1.0,
259			Method:     "image_generation_tool",
260		}
261		logging.ComponentDebugEvent("extproc", "modality_forced", map[string]interface{}{
262			"request_id": ctx.RequestID,
263			"modality":   modality,
264			"reason":     "image_generation_tool",
265		})
266	}
267	
268	func (r *OpenAIRouter) refreshResponseAPITranslatedBody(ctx *RequestContext, requestBody []byte) {
269		if ctx.ResponseAPICtx != nil && ctx.ResponseAPICtx.IsResponseAPIRequest && len(requestBody) > 0 {
270			ctx.ResponseAPICtx.TranslatedBody = requestBody
271		}
272	}
273	
274	func (r *OpenAIRouter) reparseRequestWithMemory(
275		requestBody []byte,
276		openAIRequest *openai.ChatCompletionNewParams,
277		ctx *RequestContext,
278	) *openai.ChatCompletionNewParams {
279		if ctx.MemoryContext == "" {
280			return openAIRequest
281		}
282	
283		updatedReq, err := parseRequestForProtocol(ctx, requestBody)
284		if err != nil {
285			logging.ComponentErrorEvent("extproc", "memory_request_reparse_failed", map[string]interface{}{
286				"request_id": ctx.RequestID,
287				"error":      err.Error(),
288			})
289			return openAIRequest
290		}
291	
292		logging.ComponentDebugEvent("extproc", "memory_request_reparsed", map[string]interface{}{
293			"request_id": ctx.RequestID,
294			"body_len":   len(requestBody),
295		})
296		return updatedReq
