1	package extproc
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/tidwall/gjson"
8		"github.com/tidwall/sjson"
9	
10		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
11	)
12	
13	const (
14		maxRoutingMetadataEntries  = 32
15		maxRoutingMetadataKeyLen   = 128
16		maxRoutingMetadataValueLen = 1024
17	)
18	
19	// FastExtractResult holds fields extracted from the request body via gjson
20	// without allocating the full OpenAI SDK struct.
21	type FastExtractResult struct {
22		Model             string
23		Stream            bool
24		UserContent       string
25		PriorUserMessages []string
26		NonUserMessages   []string
27		HasAssistantReply bool
28		FirstImageURL     string
29		ImageContentCount int
30		Metadata          map[string]string
31	
32		// Conversation-shape fields for the conversation signal family.
33		HasDeveloperMessage     bool
34		UserMessageCount        int
35		AssistantMessageCount   int
36		SystemMessageCount      int
37		ToolMessageCount        int
38		ToolDefinitionCount     int
39		AssistantToolCallCount  int
40		ToolResultCount         int
41		AssistantToolNames      []string
42		LastMessageRole         string
43		LastMessageToolResult   bool
44		LastUserAfterToolResult bool
45	}
46	
47	// extractContentFast extracts model, stream, message content, and the first
48	// image URL from raw JSON bytes using gjson. This avoids the two expensive
49	// json.Unmarshal calls (extractStreamParam + parseOpenAIRequest) that dominate
50	// E2E latency for large request bodies (~300ms for 64KB → ~1ms with gjson).
51	func extractContentFast(body []byte) (*FastExtractResult, error) {
52		r := &FastExtractResult{}
53		if err := extractModelAndStreamFast(body, r); err != nil {
54			return nil, err
55		}
56		if err := extractMetadataFast(body, r); err != nil {
57			return nil, err
58		}
59	
60		messages := gjson.GetBytes(body, "messages")
61		if !messages.Exists() || !messages.IsArray() {
62			return r, nil
63		}
64	
65		populateFastExtractMessages(messages, r)
66		countFastToolDefinitions(body, r)
67	
68		return r, nil
69	}
70	
71	func countFastToolDefinitions(body []byte, result *FastExtractResult) {
72		tools := gjson.GetBytes(body, "tools")
73		if !tools.Exists() || !tools.IsArray() {
74			return
75		}
76		tools.ForEach(func(_, _ gjson.Result) bool {
77			result.ToolDefinitionCount++
78			return true
79		})
80	}
81	
82	func extractMetadataFast(body []byte, result *FastExtractResult) error {
83		metadata := gjson.GetBytes(body, "metadata")
84		if !metadata.Exists() {
85			return nil
86		}
87		if !metadata.IsObject() {
88			return &jsonTypeError{field: "metadata", want: "object", got: metadata.Type.String()}
89		}
90		values := make(map[string]string)
