1	package config
2	
3	import (
4		"fmt"
5		"net/url"
6		"slices"
7		"strings"
8	)
9	
10	// RecipeName identifies an isolated routing namespace.
11	type RecipeName string
12	
13	// DefaultRecipeName names the routing profile normalized from the top-level
14	// `routing:` block. Additional named profiles come from `recipes:`.
15	const DefaultRecipeName RecipeName = "default"
16	
17	// RoutingStrategy controls how matching decisions are ordered within one
18	// routing profile.
19	type RoutingStrategy string
20	
21	const (
22		RoutingStrategyPriority   RoutingStrategy = "priority"
23		RoutingStrategyConfidence RoutingStrategy = "confidence"
24		routingNamespaceSeparator                 = "::"
25	)
26	
27	// Validate rejects strategy values outside the public routing contract.
28	func (s RoutingStrategy) Validate() error {
29		switch s {
30		case "", RoutingStrategyPriority, RoutingStrategyConfidence:
31			return nil
32		default:
33			return fmt.Errorf("routing.strategy must be %q or %q, got %q", RoutingStrategyPriority, RoutingStrategyConfidence, s)
34		}
35	}
36	
37	// RoutingProfile contains all state whose names and execution are isolated by
38	// a recipe. Shared provider bindings, model assets, and runtime services stay
39	// on RouterConfig.
40	type RoutingProfile struct {
41		Signals     Signals
42		Projections Projections
43		Decisions   []Decision
44		Strategy    RoutingStrategy
45	}
46	
47	// RoutingRecipe gives an isolated routing profile a stable name and optional
48	// request-facing description.
49	type RoutingRecipe struct {
50		Name        RecipeName
51		Description string
52		Profile     RoutingProfile
53	}
54	
55	// EntrypointMapping binds request-facing virtual model names to a named
56	// recipe. The virtual names never reach a backend; they only select which
57	// routing profile evaluates the request.
58	type EntrypointMapping struct {
59		ModelNames []string
60		Recipe     RecipeName
61	}
62	
63	// RoutingDecisionRef identifies a decision inside its owning recipe. The
64	// object pointer is stable after startup because normalized configs are
65	// immutable.
66	type RoutingDecisionRef struct {
67		Recipe   RecipeName
68		Decision *Decision
69	}
70	
71	// RoutingNamespaceKey returns a readable internal key for any recipe-local
72	// name. Public API fields continue to expose the local name alongside recipe.
73	func RoutingNamespaceKey(recipeName RecipeName, localName string) string {
74		localName = strings.TrimSpace(localName)
75		if localName == "" {
76			return ""
77		}
78		scope := RoutingNamespaceScope(recipeName)
79		if scope == "" {
80			return localName
81		}
82		return scope + routingNamespaceSeparator + url.QueryEscape(localName)
83	}
84	
85	// RoutingNamespaceScope returns the escaped storage component for a named
86	// recipe. The default recipe intentionally keeps existing unscoped keys.
87	func RoutingNamespaceScope(recipeName RecipeName) string {
88		normalizedRecipe := RecipeName(strings.TrimSpace(string(recipeName)))
89		if normalizedRecipe == "" {
90			normalizedRecipe = DefaultRecipeName
91		}
92		if normalizedRecipe == DefaultRecipeName {
93			return ""
94		}
95		return url.QueryEscape(string(normalizedRecipe))
96	}
97	
98	// RoutingDecisionKey is the decision-specific spelling of RoutingNamespaceKey.
99	func RoutingDecisionKey(recipeName RecipeName, decisionName string) string {
100		return RoutingNamespaceKey(recipeName, decisionName)
101	}
102	
103	// RoutingDecisionRefs returns every decision with its owning recipe for
104	// startup inventory such as replay-recorder and selector initialization.
105	func (c *RouterConfig) RoutingDecisionRefs() []RoutingDecisionRef {
106		if c == nil {
107			return nil
108		}
109		if len(c.Recipes) == 0 {
110			refs := make([]RoutingDecisionRef, 0, len(c.Decisions))
111			for i := range c.Decisions {
112				refs = append(refs, RoutingDecisionRef{Recipe: DefaultRecipeName, Decision: &c.Decisions[i]})
113			}
114			return refs
115		}
116		refs := make([]RoutingDecisionRef, 0)
117		for i := range c.Recipes {
118			recipe := &c.Recipes[i]
119			for j := range recipe.Profile.Decisions {
120				refs = append(refs, RoutingDecisionRef{Recipe: recipe.Name, Decision: &recipe.Profile.Decisions[j]})
121			}
122		}
123		return refs
124	}
125	
126	// RecipeByName returns the normalized recipe with the given name.
127	func (c *RouterConfig) RecipeByName(name RecipeName) (*RoutingRecipe, bool) {
128		if c == nil {
129			return nil, false
130		}
131		for i := range c.Recipes {
132			if c.Recipes[i].Name == name {
133				return &c.Recipes[i], true
134			}
135		}
136		return nil, false
137	}
138	
139	// DefaultRecipe returns the recipe backing the flat routing fields. Canonical
140	// configs contain an explicit normalized default recipe; programmatically
141	// assembled single-profile configs get an equivalent immutable view so callers
142	// do not need a second routing path.
143	func (c *RouterConfig) DefaultRecipe() *RoutingRecipe {
144		if c == nil {
145			return nil
146		}
147		recipe, ok := c.RecipeByName(DefaultRecipeName)
148		if ok {
149			return recipe
150		}
151		return &RoutingRecipe{
152			Name: DefaultRecipeName,
153			Profile: RoutingProfile{
154				Signals:     c.Signals,
155				Projections: c.Projections,
156				Decisions:   c.Decisions,
157				Strategy:    c.Strategy,
158			},
159		}
160	}
161	
162	// RecipeForRequestModel resolves a request model name through the entrypoint
163	// table. It returns false when the name matches no entrypoint; callers fall
164	// back to auto-model or specified-model handling.
165	func (c *RouterConfig) RecipeForRequestModel(modelName string) (*RoutingRecipe, bool) {
166		if c == nil {
167			return nil, false
168		}
169		trimmed := strings.TrimSpace(modelName)
170		if trimmed == "" {
171			return nil, false
172		}
173		for _, entrypoint := range c.Entrypoints {
174			if slices.Contains(entrypoint.ModelNames, trimmed) {
175				return c.RecipeByName(entrypoint.Recipe)
176			}
177		}
178		return nil, false
179	}
180	
181	// RecipeForRoutingModel resolves every request-facing routing model. Built-in
182	// auto and direct-looper aliases select the default recipe; named entrypoints
183	// select their mapped recipe. Concrete backend model IDs intentionally do not
184	// resolve to a recipe.
185	func (c *RouterConfig) RecipeForRoutingModel(modelName string) (*RoutingRecipe, bool) {
186		if c == nil {
187			return nil, false
188		}
189		trimmed := strings.TrimSpace(modelName)
190		if c.IsAutoModelName(trimmed) || c.IsReMoMModelName(trimmed) || c.IsFusionModelName(trimmed) || c.IsFlowModelName(trimmed) {
191			recipe := c.DefaultRecipe()
192			return recipe, recipe != nil
193		}
194		return c.RecipeForRequestModel(modelName)
195	}
196	
197	// ConfigForRecipe returns an immutable routing view over the shared router
198	// configuration. The returned value owns recipe-local routing fields while
199	// reusing read-only provider, model, and service configuration. Callers must
200	// not mutate either the returned config or the source config after startup.
201	func (c *RouterConfig) ConfigForRecipe(recipe *RoutingRecipe) *RouterConfig {
202		if c == nil || recipe == nil {
203			return nil
204		}
205	
206		scoped := *c
207		scoped.RoutingScope = recipe.Name
208		scoped.IntelligentRouting = IntelligentRouting{
209			Signals:         recipe.Profile.Signals,
210			Projections:     recipe.Profile.Projections,
211			Decisions:       recipe.Profile.Decisions,
212			Strategy:        recipe.Profile.Strategy,
213			ModelSelection:  c.ModelSelection,
214			ReasoningConfig: c.ReasoningConfig,
215		}
216		scoped.KnowledgeBases = knowledgeBasesForRoutingProfile(c.KnowledgeBases, recipe.Profile)
217		// A scoped config represents exactly one routing profile. Keeping the full
218		// recipe list here would make helpers such as AllRoutingDecisions escape the
219		// selected recipe again.
220		scoped.Recipes = nil
221		return &scoped
222	}
223	
224	func knowledgeBasesForRoutingProfile(catalog []KnowledgeBaseConfig, profile RoutingProfile) []KnowledgeBaseConfig {
225		referenced := make(map[string]struct{}, len(profile.Signals.KBRules))
226		for _, rule := range profile.Signals.KBRules {
227			if rule.KB != "" {
228				referenced[rule.KB] = struct{}{}
229			}
230		}
231		for _, score := range profile.Projections.Scores {
232			for _, input := range score.Inputs {
233				if strings.EqualFold(input.Type, ProjectionInputKBMetric) && input.KB != "" {
234					referenced[input.KB] = struct{}{}
235				}
236			}
237		}
238		if len(referenced) == 0 {
239			return nil
240		}
241	
242		filtered := make([]KnowledgeBaseConfig, 0, len(referenced))
243		for _, kb := range catalog {
244			if _, ok := referenced[kb.Name]; ok {
245				filtered = append(filtered, kb)
246			}
247		}
248		return filtered
249	}
250	
251	// IsEntrypointModelName reports whether the name is a request-facing virtual
252	// model name from the entrypoint table. Such names never reach a backend; the
253	// router resolves them like auto-model aliases.
254	func (c *RouterConfig) IsEntrypointModelName(modelName string) bool {
255		_, ok := c.RecipeForRequestModel(modelName)
256		return ok
257	}
258	
259	// EntrypointRecipeDescription returns the model-listing description for an
260	// entrypoint's recipe: the recipe's own description when set, otherwise a
261	// generic label naming the recipe.
262	func (c *RouterConfig) EntrypointRecipeDescription(recipeName RecipeName) string {
263		if recipe, ok := c.RecipeByName(recipeName); ok && strings.TrimSpace(recipe.Description) != "" {
264			return recipe.Description
265		}
266		return fmt.Sprintf("Entrypoint for the %s routing recipe", recipeName)
267	}
268	
269	// AllRoutingDecisions returns the decisions of every routing profile for
270	// startup-only resource discovery and whole-config inventory. Request-time
271	// routing must use ConfigForRecipe instead.
272	func (c *RouterConfig) AllRoutingDecisions() []Decision {
273		if c == nil {
274			return nil
275		}
276		if len(c.Recipes) == 0 {
277			return c.Decisions
278		}
279		if len(c.Recipes) == 1 {
280			return c.Recipes[0].Profile.Decisions
281		}
282		all := make([]Decision, 0, 2*len(c.Decisions))
283		for i := range c.Recipes {
284			all = append(all, c.Recipes[i].Profile.Decisions...)
285		}
286		return all
287	}
288	
289	// HasRoutingDecisions reports whether any routing profile declares decisions,
290	// without the per-request allocation of AllRoutingDecisions. The flat gate
291	// `len(c.Decisions) == 0` is wrong for recipes-only configs, where every
292	// decision lives in a non-default recipe.
293	func (c *RouterConfig) HasRoutingDecisions() bool {
294		if c == nil {
295			return false
296		}
297		if len(c.Decisions) > 0 {
298			return true
299		}
300		for i := range c.Recipes {
301			if len(c.Recipes[i].Profile.Decisions) > 0 {
302				return true
303			}
304		}
305		return false
306	}
307	
308	// RoutingProfileSignals returns the default profile's signals for canonical
309	// export. The flat Signals field mirrors this value for single-profile readers.
310	func (c *RouterConfig) RoutingProfileSignals() Signals {
311		if c == nil {
312			return Signals{}
313		}
314		if recipe := c.DefaultRecipe(); recipe != nil {
315			return recipe.Profile.Signals
316		}
317		return c.Signals
318	}
319	
320	// RoutingProfileProjections is the projections counterpart of
321	// RoutingProfileSignals.
322	func (c *RouterConfig) RoutingProfileProjections() Projections {
323		if c == nil {
324			return Projections{}
325		}
326		if recipe := c.DefaultRecipe(); recipe != nil {
327			return recipe.Profile.Projections
328		}
329		return c.Projections
330	}
